<script>
  const slider = document.querySelector('.owl-demo-6');

  let pos = 0,
    dragging = false,
    startX = 0,
    startPos = 0;
  const speed = 1;

  function move() {
    if (!dragging) {
      pos -= speed;

      if (Math.abs(pos) >= slider.scrollWidth / 2)
        pos = 0;

      slider.style.transform = `translateX(${pos}px)`;
    }

    requestAnimationFrame(move);
  }

  function limitPosition() {
    const max = -(slider.scrollWidth / 2);

    if (pos > 0) pos = 0;
    if (pos < max) pos = max;
  }


  // Mouse
  slider.onmousedown = e => {
    dragging = true;
    startX = e.pageX;
    startPos = pos;
  };

  document.onmousemove = e => {
    if (dragging) {
      pos = startPos + e.pageX - startX;

      limitPosition();

      slider.style.transform = `translateX(${pos}px)`;
    }
  };

  document.onmouseup = () => dragging = false;


  // Mobile
  slider.ontouchstart = e => {
    dragging = true;
    startX = e.touches[0].pageX;
    startPos = pos;
  };

  slider.ontouchmove = e => {
    if (dragging) {
      pos = startPos + e.touches[0].pageX - startX;

      limitPosition();

      slider.style.transform = `translateX(${pos}px)`;
    }
  };

  slider.ontouchend = () => dragging = false;

  move();
</script>
